content.content:
Target (Claude Code, user scope):
  brain      new keyless PGLite brain at /harness-state/.gbrain/brain.pglite (gbrain init --pglite --no-embedding)
  source     the brain's default source (unpinned)
  transport  stdio MCP: /harness-state/.gbrain/hook-launcher/gbrain-hook /harness-state/.bun/bin/gbrain serve --surface starter --advertise verbs (lists the memory verbs and request_tools; every starter tool stays callable)
  owner      none yet; setup will own 'gbrain'
  files      /harness-state/claude/.claude.json (MCP), /harness-state/claude/settings.json (hooks)
Decisions:
  wiring     user scope; hooks SessionStart, UserPromptSubmit [default]
  capture    declined (no Stop/SessionEnd hooks, no transcript capture; accept with --capture) [default]
  providers  declined (keyless: setup configures no paid provider; accept with --providers) [default]
{
  "harness": "claude-code",
  "dry_run": true,
  "remove": false,
  "target": {
    "brain": {
      "kind": "new-local-pglite",
      "path": "/harness-state/.gbrain/brain.pglite",
      "config_dir": "/harness-state/.gbrain"
    },
    "source": {
      "id": null,
      "pinned": false,
      "from": "brain-default"
    },
    "transport": "local-stdio",
    "launcher": "/harness-state/.bun/bin/gbrain",
    "surface": "starter",
    "advertise": "verbs",
    "registration_owner": "none",
    "live_owner": null,
    "scope": "user",
    "name": "gbrain",
    "config_path": "/harness-state/claude/.claude.json",
    "settings_path": "/harness-state/claude/settings.json",
    "receipt_path": "/harness-state/claude/.gbrain-connection-claude-code-gbrain.json"
  },
  "consent": {
    "wiring_scope": {
      "value": {
        "scope": "user",
        "hooks": "read-context"
      },
      "source": "default"
    },
    "capture": {
      "value": "declined",
      "source": "default"
    },
    "providers": {
      "value": "declined",
      "source": "default"
    }
  },
  "steps": [
    {
      "step": "receipt",
      "action": "write",
      "detail": "/harness-state/claude/.gbrain-connection-claude-code-gbrain.json"
    },
    {
      "step": "brain",
      "action": "write",
      "detail": "would run: /harness-state/.bun/bin/gbrain init --pglite --no-embedding --json"
    },
    {
      "step": "mcp",
      "action": "write",
      "detail": "'gbrain' in /harness-state/claude/.claude.json"
    },
    {
      "step": "hooks",
      "action": "write",
      "detail": "SessionStart, UserPromptSubmit in /harness-state/claude/settings.json"
    }
  ],
  "preserved": [],
  "instructions": {
    "harness": "claude-code",
    "path": "/harness-state/claude/CLAUDE.md",
    "role": "Claude Code user instructions",
    "decision": {
      "value": "accepted",
      "source": "default"
    },
    "action": "write",
    "state_before": "no_file",
    "detail": "brain-first block in new file /harness-state/claude/CLAUDE.md"
  },
  "skills": {
    "harness": "claude-code",
    "path": "/harness-state/claude/CLAUDE.md",
    "decision": {
      "value": "off",
      "source": "default"
    },
    "action": "skip",
    "state_before": "no_file",
    "detail": "skill loading off: no skills index in /harness-state/claude/CLAUDE.md"
  },
  "states": [],
  "state": null,
  "verify": null,
  "capability": {
    "harness": "claude-code",
    "transport": "local-stdio",
    "setup": "supported",
    "pull": "connection-verified",
    "push": "native-pending",
    "read_events": [
      "SessionStart",
      "UserPromptSubmit"
    ],
    "capture_events": [
      "Stop",
      "SessionEnd"
    ],
    "docs": "docs/mcp/CLAUDE_CODE.md"
  },
  "capability_table_version": 2,
  "notes": [],
  "notices": [
    {
      "code": "first_run_decisions",
      "kind": "ask",
      "why": "Setup is complete and memory works now. One optional choice remains; nothing is written until the user answers.",
      "user_message": "gbrain is set up, so memory works now. Want a personal or company brain? I can add starter pages (facts, voice and decisions) and import a notes or docs folder you pick.",
      "decisions": [
        {
          "id": "brain_shape",
          "question": "Give this brain a shape? A personal brain gets three empty starter pages (facts about you, your voice, how you decide) and a notes folder you pick, imported read only. A company brain gets empty pages for company facts, decisions, pricing, customers, calls and playbooks in a company source, and a docs folder you pick. Setup tells the agent to read them. Nothing is invented.",
          "options": [
            {
              "id": "personal",
              "label": "Personal brain, no notes folder yet",
              "argv": [
                "gbrain",
                "setup",
                "claude-code",
                "--shape",
                "personal"
              ]
            },
            {
              "id": "company",
              "label": "Company brain, just me (add --docs <folder> for company docs, --transcripts <folder> for call transcripts)",
              "argv": [
                "gbrain",
                "setup",
                "claude-code",
                "--shape",
                "company"
              ]
            },
            {
              "id": "both",
              "label": "Personal and company brain, just me",
              "argv": [
                "gbrain",
                "setup",
                "claude-code",
                "--shape",
                "both"
              ]
            },
            {
              "id": "company_team",
              "label": "Company brain shared with a team (prints where it lives; creates nothing)",
              "argv": [
                "gbrain",
                "setup",
                "claude-code",
                "--shape",
                "company",
                "--team"
              ]
            },
            {
              "id": "none",
              "label": "No starter pages (memory works as it is)"
            }
          ],
          "default": "none",
          "default_reason": "Nothing is written until the user picks; memory already works without it."
        }
      ],
      "contract_version": 1
    }
  ]
}

