content.content:
state "native-pending"
states [
 "configured",
 "connection-verified",
 "native-pending"
]
verify {
 "ok": true,
 "reason": "smoke_passed",
 "message": "initialize, tools/list (8 tools) and recall answered."
}
preserved []
notes []
instructions {
 "harness": "claude-code",
 "path": "/harness-state/claude/CLAUDE.md",
 "role": "Claude Code user instructions",
 "decision": {
  "value": "accepted",
  "source": "default"
 },
 "action": "write",
 "state_before": "no_file",
 "detail": "brain-first block in new file /harness-state/claude/CLAUDE.md"
}
{
 "code": "first_run_decisions",
 "kind": "ask",
 "why": "Setup is complete: the brain is ready and Claude Code is wired, so memory works now. These first-run settings are in effect as listed; none blocks memory or needs a new session to answer. Relay them once, in the reply that reports this install, as the current settings and how to change them; do not hold the install open or end it waiting on an answer. When the user picks an option, run its command. Automatic saving (`writeback`) is separate from setup's capture decision (Stop/SessionEnd hooks); while unanswered it comes back in a later session until the user answers or mutes it.",
 "user_message": "gbrain is set up and Claude Code is wired, so memory works now. In effect: search mode conservative; agents save only what you ask them to remember, until you turn on automatic saving (salient is recommended: durable facts you state, saved with provenance). Report back (Wakeshift): off. gbrain wakeshift enable turns it on. Upkeep: free upkeep runs on its own while your agent's gbrain session is open. Nothing is deleted or paid for without you. Turn off: gbrain config set maintenance.auto false. Optional schedule: gbrain maintain --schedule. Conversation archive: on. gbrain keeps one redacted page per conversation per day from your agent sessions (Claude Code, Codex, OpenClaw, Hermes, Grok) in the conversations source, written by the maintenance pass. Without an embedding key nothing leaves this machine. Turn off: gbrain transcripts archive off. Estimated downstream input cost of the retrieved payload at 10K queries/month (Haiku 5.5 / Sonnet 5.5 / Opus 5.5): conservative $4 / $80 / $160, balanced $10 / $200 / $400, tokenmax $20 / $400 / $800 per month. Nothing needs an answer now; tell me any time if you want to change any of these, and I'll apply it. Want a personal or company brain? I can add starter pages (facts, voice and decisions) and import a notes or docs folder you pick.",
 "decisions": [
  {
   "id": "search_mode",
   "question": "Which search mode should this brain use? Estimated downstream input cost of the retrieved payload at 10K queries/month (Haiku 5.5 / Sonnet 5.5 / Opus 5.5): conservative $4 / $80 / $160, balanced $10 / $200 / $400, tokenmax $20 / $400 / $800 per month.",
   "options": [
    {
     "id": "conservative",
     "label": "conservative (applied)",
     "argv": [
      "gbrain",
      "config",
      "set",
      "search.mode",
      "conservative"
     ]
    },
    {
     "id": "balanced",
     "label": "balanced",
     "argv": [
      "gbrain",
      "config",
      "set",
      "search.mode",
      "balanced"
     ]
    },
    {
     "id": "tokenmax",
     "label": "tokenmax",
     "argv": [
      "gbrain",
      "config",
      "set",
      "search.mode",
      "tokenmax"
     ]
    }
   ],
   "default": "conservative",
   "default_reason": "No chat key (Anthropic/OpenAI/Google) and no ready reranker — conservative keeps a tight 4K budget; balanced's reranker could not run."
  },
  {
   "id": "writeback",
   "question": "Should agents save important facts the user states (preferences, decisions, commitments) automatically, with provenance? Saved facts are readable by agents connected to this brain; transient facts expire. Off any time with `gbrain config set memory.auto_writeback off`.",
   "options": [
    {
     "id": "salient",
     "label": "Save durable facts the user states directly (recommended)",
     "argv": [
      "gbrain",
      "config",
      "set",
      "memory.auto_writeback",
      "salient"
     ]
    },
    {
     "id": "all",
     "label": "Every direct factual statement (more low-value facts, more extraction spend)",
     "argv": [
      "gbrain",
      "config",
      "set",
      "memory.auto_writeback",
      "all"
     ]
    },
    {
     "id": "off",
     "label": "Save only what the user explicitly asks to remember (records the answer)",
     "argv": [
      "gbrain",
      "config",
      "set",
      "memory.auto_writeback",
      "off"
     ]
    }
   ],
   "default": "off",
   "default_reason": "In effect now: agents save only what the user asks them to remember. salient is recommended for a personal brain; it is opt-in, so it turns on only when the user picks it."
  },
  {
   "id": "upkeep",
   "question": "Upkeep: free upkeep runs on its own while your agent's gbrain session is open. Nothing is deleted or paid for without you. Turn off: gbrain config set maintenance.auto false. Optional schedule: gbrain maintain --schedule.",
   "options": [
    {
     "id": "on",
     "label": "Keep free upkeep on (in effect now)"
    },
    {
     "id": "off",
     "label": "Turn free upkeep off",
     "argv": [
      "gbrain",
      "config",
      "set",
      "maintenance.auto",
      "false"
     ]
    }
   ],
   "default": "on",
   "default_reason": "In effect now: the agent's gbrain serve runs the free upkeep tier while idle; nothing needs an answer."
  },
  {
   "id": "conversation_archive",
   "question": "Conversation archive: on. gbrain keeps one redacted page per conversation per day from your agent sessions (Claude Code, Codex, OpenClaw, Hermes, Grok) in the conversations source, written by the maintenance pass. Without an embedding key nothing leaves this machine. Turn off: gbrain transcripts archive off.",
   "options": [
    {
     "id": "on",
     "label": "Keep the conversation archive on (in effect now)"
    },
    {
     "id": "off",
     "label": "Turn the conversation archive off",
     "argv": [
      "gbrain",
      "transcripts",
      "archive",
      "off"
     ]
    }
   ],
   "default": "on",
   "default_reason": "In effect now: on by default on a personal brain; nothing needs an answer."
  },
  {
   "id": "brain_shape",
   "question": "Give this brain a shape? A personal brain gets three empty starter pages (facts about you, your voice, how you decide) and a notes folder you pick, imported read only. A company brain gets empty pages for company facts, decisions, pricing, customers, calls and playbooks in a company source, and a docs folder you pick. Setup tells the agent to read them. Nothing is invented.",
   "options": [
    {
     "id": "personal",
     "label": "Personal brain, no notes folder yet",
     "argv": [
      "gbrain",
      "setup",
      "claude-code",
      "--shape",
      "personal"
     ]
    },
    {
     "id": "company",
     "label": "Company brain, just me (add --docs <folder> for company docs, --transcripts <folder> for call transcripts)",
     "argv": [
      "gbrain",
      "setup",
      "claude-code",
      "--shape",
      "company"
     ]
    },
    {
     "id": "both",
     "label": "Personal and company brain, just me",
     "argv": [
      "gbrain",
      "setup",
      "claude-code",
      "--shape",
      "both"
     ]
    },
    {
     "id": "company_team",
     "label": "Company brain shared with a team (prints where it lives; creates nothing)",
     "argv": [
      "gbrain",
      "setup",
      "claude-code",
      "--shape",
      "company",
      "--team"
     ]
    },
    {
     "id": "none",
     "label": "No starter pages (memory works as it is)"
    }
   ],
   "default": "none",
   "default_reason": "Nothing is written until the user picks; memory already works without it."
  }
 ],
 "contract_version": 1
}
{
 "code": "hosted_option",
 "kind": "coaching",
 "why": "gbrain.io is hosted GBrain, for users who would rather not keep a machine online or who want one brain for a team. Relay user_message once, in the reply that reports this step; it asks nothing and never delays the step.",
 "user_message": "Hosted option: gbrain.io runs GBrain for you, with nothing to keep online, and can import this brain: https://gbrain.io/?ref=cli-setup. Mute: gbrain notices mute hosted_option.",
 "contract_version": 1
}
Shell cwd was reset to /workspace

