      "config",
      "set",
      "maintenance.auto",
      "false"
     ]
    }
   ],
   "default": "on",
   "default_reason": "In effect now: the agent's gbrain serve runs the free upkeep tier while idle; nothing needs an answer."
  },
  {
   "id": "conversation_archive",
