input.command:
mkdir -p /tmp/gbrain-scripts && cat > /tmp/gbrain-scripts/mcp.mjs <<'EOF'
import { spawn } from 'node:child_process';
const p = spawn('/harness-state/.gbrain/hook-launcher/gbrain-hook',
  ['/harness-state/.bun/bin/gbrain','serve','--surface','starter','--advertise','verbs'], {stdio:['pipe','pipe','inherit']});
let buf='', id=0; const waiters={};
p.stdout.on('data', d=>{buf+=d; let i; while((i=buf.indexOf('\n'))>=0){const l=buf.slice(0,i);buf=buf.slice(i+1); try{const m=JSON.parse(l); if(waiters[m.id]){waiters[m.id](m);delete waiters[m.id];}}catch{}}});
const rpc=(method,params)=>new Promise(r=>{const i=++id;waiters[i]=r;p.stdin.write(JSON.stringify({jsonrpc:'2.0',id:i,method,params})+'\n');});
await rpc('initialize',{protocolVersion:'2025-06-18',capabilities:{},clientInfo:{name:'install-check',version:'1'}});
p.stdin.write(JSON.stringify({jsonrpc:'2.0',method:'notifications/initialized'})+'\n');
const tools=await rpc('tools/list',{}); console.log('tools:', tools.result.tools.map(t=>t.name).join(', '));
const show=r=>console.log(JSON.stringify(r.result?.content?.map(c=>c.text).join('\n') ?? r.error).slice(0,700));
console.log('== MCP remember'); show(await rpc('tools/call',{name:'remember',arguments:{fact:'GBrain MCP install check note 2026-11-17: written via the gbrain MCP server',entity:'gbrain-install-check',provenance:'install-check',content_origin:'inferred'}}));
console.log('== MCP recall'); show(await rpc('tools/call',{name:'recall',arguments:{entity:'gbrain-install-check'}}));
p.kill();
EOF
cd /tmp && node /tmp/gbrain-scripts/mcp.mjs
